-- Decisões de organização documental por identidade/hash/trecho de origem.
-- Acrescentar NR35 não aprova engenharia, não reabre pendência e não autoriza PET.
create table public.nr_aplicabilidade_decisoes(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),
 pendencia_id uuid,pendencia_esperada_id uuid not null,fonte_id uuid references public.nr_fontes(id),
 sistema_origem text not null,externo_id text not null,fonte_sha256 text not null check(fonte_sha256~'^[a-f0-9]{64}$'),
 fonte_sha256_encontrado text,versao text not null,request_sha256 text not null check(request_sha256~'^[a-f0-9]{64}$'),
 decisao text not null check(decisao in('incluir_nr35','manter_recorte','revisao_pendente')),
 resultado text not null check(resultado in('aplicada','mantida','pendente_analise','pendente_divergencia','sem_correspondencia')),
 normas_anteriores text[],normas_decididas text[] not null,normas_aplicadas text[],
 justificativa text not null check(length(justificativa)between 3 and 4000),motivo_resultado text not null,
 evidencias jsonb not null check(jsonb_typeof(evidencias)='array'),registro_sha256_antes text,registro_sha256_apos text,
 aprovacao_profissional boolean not null default false check(not aprovacao_profissional),
 autoriza_operacao boolean not null default false check(not autoriza_operacao),
 executor text not null default session_user,created_at timestamptz not null default now(),
 unique(organization_id,id),unique(organization_id,sistema_origem,externo_id,versao),
 foreign key(organization_id,pendencia_id)references public.nr_pendencias(organization_id,id)
);
create index nr_aplicabilidade_pendencia on public.nr_aplicabilidade_decisoes(organization_id,pendencia_id,created_at desc,id);
create index nr_aplicabilidade_resultado on public.nr_aplicabilidade_decisoes(organization_id,resultado,created_at desc,id);
alter table public.nr_aplicabilidade_decisoes enable row level security;
revoke all on public.nr_aplicabilidade_decisoes from public,anon,authenticated,service_role;
grant select on public.nr_aplicabilidade_decisoes to authenticated;
create policy nr_aplicabilidade_ler on public.nr_aplicabilidade_decisoes for select to authenticated using(public.pode(organization_id,'ver_nr'));
create trigger nr_aplicabilidade_imutavel before update or delete on public.nr_aplicabilidade_decisoes for each row execute function public.pet_imutavel();

-- Execução proprietária de um manifesto versionado. Nunca exposta aos papéis da aplicação.
create function public.nr_aplicabilidade_manifesto_aplicar(p_org uuid,p_sistema text,p_versao text,p_manifesto jsonb)returns jsonb
language plpgsql security definer set search_path=''as $$
<<aplicar>>
declare item jsonb;p public.nr_pendencias;f public.nr_fontes;existente public.nr_aplicabilidade_decisoes;
 esperado uuid;cliente uuid;unidade uuid;local uuid;normas text[];anterior jsonb;apos jsonb;hash text;
 resultado text;motivo text;justificativa text;trecho jsonb;prova boolean;decisao text;repetidos integer:=0;novos integer:=0;begin
 if p_org is null or length(coalesce(p_sistema,''))not between 3 and 500 or length(coalesce(p_versao,''))not between 3 and 120 or jsonb_typeof(p_manifesto)is distinct from 'array'or jsonb_array_length(p_manifesto)>10000 or octet_length(p_manifesto::text)>10000000 then raise exception 'Manifesto de aplicabilidade inválido.'using errcode='23514';end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('nr-aplicabilidade:'||p_org::text||':'||p_versao,0));
 for item in select value from jsonb_array_elements(p_manifesto)order by value->>'externo_id'loop
  if jsonb_typeof(item)is distinct from 'object'or length(coalesce(item->>'externo_id',''))not between 3 and 1000 or coalesce(item->>'fonte_sha256','')!~'^[a-f0-9]{64}$'then raise exception 'Identidade ou hash da decisão inválido.'using errcode='23514';end if;
  esperado:=(item->>'destino_id')::uuid;cliente:=(item->>'cliente_id')::uuid;unidade:=(item->>'unidade_id')::uuid;local:=nullif(item->>'local_id','')::uuid;
  decisao:=item->>'decisao';justificativa:=item->>'justificativa';
  select array_agg(value order by ordinality)into normas from jsonb_array_elements_text(item->'normas')with ordinality;
  if esperado is null or cliente is null or unidade is null or decisao is null or decisao not in('incluir_nr35','manter_recorte','revisao_pendente')or length(coalesce(justificativa,''))not between 3 and 4000 or normas is null or cardinality(normas)not between 1 and 2 or not normas<@array['NR33','NR35']::text[]or(cardinality(normas)=2 and normas[1]=normas[2])or jsonb_typeof(item->'evidencias')is distinct from 'array'then raise exception 'Decisão ou contexto inválido.'using errcode='23514';end if;
  if decisao='incluir_nr35'and(not normas@>array['NR33','NR35']::text[]or jsonb_array_length(item->'evidencias')=0)then raise exception 'A ampliação precisa manter NR33 e apresentar evidência própria.'using errcode='23514';end if;
  hash:=public.pet_sha256(item);
  select * into existente from public.nr_aplicabilidade_decisoes d where d.organization_id=p_org and d.sistema_origem=p_sistema and d.externo_id=item->>'externo_id'and d.versao=p_versao;
  if found then
   if existente.request_sha256<>hash then raise exception 'Versão de decisão já utilizada com outro conteúdo.'using errcode='23505';end if;
   repetidos:=repetidos+1;continue;
  end if;
  -- Mesma ordem de trava do importador: fonte antes do registro.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('nr-fonte:'||p_org::text||':'||p_sistema||':pendencia:'||(item->>'externo_id'),0));
  select * into f from public.nr_fontes sf where sf.organization_id=p_org and sf.origem=p_sistema and sf.tipo='pendencia'and sf.externo_id=item->>'externo_id'for update;
  select * into p from public.nr_pendencias where organization_id=p_org and id=esperado for update;
  anterior:=case when found then to_jsonb(p)else null end;
  resultado:='pendente_divergencia';motivo:='A fonte ou o registro atual diverge da identidade, do hash ou do snapshot esperado. Nenhum campo foi alterado.';
  if anterior is null then resultado:='sem_correspondencia';motivo:='O UUID esperado da pendência não existe nesta organização; nenhuma correspondência por nome foi inferida.';
  elsif f.id is not null and f.destino_tipo='pendencias'and f.destino_id=esperado and f.sha256=item->>'fonte_sha256'and p.cliente_id=cliente and p.unidade_id=unidade and p.local_id is not distinct from local and f.snapshot_destino is not null and anterior=f.snapshot_destino then
   prova:=true;
   for trecho in select value from jsonb_array_elements(item->'evidencias')loop
    if trecho->>'campo'not in('titulo','descricao','desfecho','conclusao','encaminhamento')or length(coalesce(trecho->>'trecho',''))<3 or position(trecho->>'trecho'in coalesce(f.payload->>(trecho->>'campo'),''))=0 or coalesce(trecho->>'campo_sha256','')<>encode(sha256(convert_to(coalesce(f.payload->>(trecho->>'campo'),''),'UTF8')),'hex')then prova:=false;end if;
   end loop;
   if not prova then motivo:='O trecho ou seu hash não corresponde ao campo da própria fonte. Nenhuma norma foi alterada.';
   elsif not p.normas<@normas then motivo:='A decisão reduziria normas já registradas; exige nova análise explícita e não foi aplicada.';
   elsif decisao='revisao_pendente'then resultado:='pendente_analise';motivo:='A menção foi registrada para análise; o manifesto não afirma enquadramento adicional.';
   elsif decisao='manter_recorte'then resultado:='mantida';motivo:='Recorte preservado sem declarar inaplicabilidade técnica de outra norma.';
   elsif p.normas@>array['NR33']::text[]then
    if p.normas is distinct from normas then
     update public.nr_pendencias set normas=aplicar.normas where organization_id=p_org and id=p.id returning * into p;
     insert into public.nr_historico(organization_id,recurso,registro_id,comando,antes,depois,motivo)values(p_org,'pendencias',p.id,'conciliar_aplicabilidade',anterior,to_jsonb(p),'Manifesto '||p_versao||'. '||justificativa);
    end if;
    resultado:='aplicada';motivo:='NR35 acrescentada ao contexto documental comprovado, preservando NR33, estado, tratativas, dados e autoria de origem.';
   else motivo:='A classificação atual não conserva NR33; a ampliação exige revisão e não foi aplicada.';
   end if;
  end if;
  apos:=case when anterior is not null then to_jsonb(p)else null end;
  insert into public.nr_aplicabilidade_decisoes(organization_id,pendencia_id,pendencia_esperada_id,fonte_id,sistema_origem,externo_id,fonte_sha256,fonte_sha256_encontrado,versao,request_sha256,decisao,resultado,normas_anteriores,normas_decididas,normas_aplicadas,justificativa,motivo_resultado,evidencias,registro_sha256_antes,registro_sha256_apos)
  values(p_org,case when anterior is not null then esperado end,esperado,f.id,p_sistema,item->>'externo_id',item->>'fonte_sha256',f.sha256,p_versao,hash,decisao,resultado,case when anterior is not null then array(select jsonb_array_elements_text(anterior->'normas'))end,normas,case when anterior is not null then p.normas end,justificativa,motivo,item->'evidencias',case when anterior is not null then public.pet_sha256(anterior)end,case when apos is not null then public.pet_sha256(apos)end);
  novos:=novos+1;
 end loop;
 return jsonb_build_object('versao',p_versao,'novas_decisoes',novos,'decisoes_ja_registradas',repetidos,'resultados',(select coalesce(jsonb_object_agg(q.resultado,q.quantidade),'{}')from(select d.resultado,count(*)quantidade from public.nr_aplicabilidade_decisoes d where d.organization_id=p_org and d.sistema_origem=p_sistema and d.versao=p_versao group by d.resultado)q));
end$$;
revoke all on function public.nr_aplicabilidade_manifesto_aplicar(uuid,text,text,jsonb)from public,anon,authenticated,service_role;

-- A ficha resolve decisões somente pelo registro autorizado já resolvido por nr_consultar.
alter function public.nr_linha(text,jsonb)rename to nr_linha_base_67;
create function public.nr_linha(p_recurso text,p_linha jsonb)returns jsonb language plpgsql stable security definer set search_path=''as $$
declare r jsonb:=public.nr_linha_base_67(p_recurso,p_linha);decisoes jsonb;begin
 if p_recurso='pendencias'then
  select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'versao',d.versao,'decisao',d.decisao,'resultado',d.resultado,'normas_anteriores',d.normas_anteriores,'normas_decididas',d.normas_decididas,'normas_aplicadas',d.normas_aplicadas,'justificativa',d.justificativa,'motivo_resultado',d.motivo_resultado,'evidencias',d.evidencias,'fonte_sha256',d.fonte_sha256,'externo_id',d.externo_id,'aprovacao_profissional',d.aprovacao_profissional,'autoriza_operacao',d.autoriza_operacao,'created_at',d.created_at)order by d.created_at desc,d.id),'[]')into decisoes from public.nr_aplicabilidade_decisoes d where d.organization_id=(r->>'organization_id')::uuid and d.pendencia_id=(r->>'id')::uuid;
  r:=r||jsonb_build_object('decisoes_aplicabilidade',decisoes);
 end if;return r;
end$$;
revoke all on function public.nr_linha(text,jsonb),public.nr_linha_base_67(text,jsonb)from public,anon,authenticated,service_role;

